insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1424','animals','Animal behavior','medium','classic','What do sea otters sometimes use as tools to open hard-shelled prey?','["Stones","Feathers","Tree bark","Coral branches"]'::jsonb,'Stones','Sea otters can use stones as tools to crack open shellfish and other hard prey.',10,2,array['animal behavior'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1425','animals','Ecology','medium','classic','How can fruit-eating bats help many plants reproduce?','["By dispersing seeds in their droppings","By turning leaves into soil without eating fruit","By pollinating only underwater flowers","By carrying roots between caves"]'::jsonb,'By dispersing seeds in their droppings','Fruit bats disperse seeds when they carry fruit and later deposit the seeds elsewhere.',10,2,array['ecology'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
