insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1428','animals','Marine life','easy','classic','Why is a sea star not classified as a fish?','["It is an echinoderm, not a fish","It breathes only with lungs","It has feathers instead of skin","It is a type of flowering plant"]'::jsonb,'It is an echinoderm, not a fish','Sea stars are echinoderms, a group of marine invertebrates, rather than fish.',10,2,array['marine life'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1429','animals','Invertebrates','medium','classic','Which statement about sponges is correct?','["They are animals without true organs","They are colonies of flowering plants","They are fish with a single fin","They are insects with six legs"]'::jsonb,'They are animals without true organs','Sponges are simple aquatic animals that lack the true tissues and organs found in many other animals.',10,2,array['invertebrates'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1430','animals','Marine life','medium','classic','What gives an octopus’s blood its blue color?','["The copper-containing protein hemocyanin","Iron-rich hemoglobin","Green chlorophyll","Calcium carbonate crystals"]'::jsonb,'The copper-containing protein hemocyanin','Octopus blood uses copper-containing hemocyanin to transport oxygen, producing a blue color.',10,2,array['marine life'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1431','animals','Mammals','medium','classic','What is regurgitated and chewed again by animals such as cows during rumination?','["Cud","A shed antler","A salt gland","A feather pellet"]'::jsonb,'Cud','Ruminants bring partially digested food, called cud, back to the mouth for further chewing.',10,2,array['mammals'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1432','animals','Animal senses','easy','classic','Which sense do snakes use their forked tongues to help collect chemical cues for?','["Smell","Hearing","Taste only","Magnetic navigation only"]'::jsonb,'Smell','A snake flicks its tongue to collect airborne chemicals and transfers them to a sensory organ in its mouth.',10,2,array['animal senses'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1433','animals','Animal behavior','medium','classic','What does hibernation generally involve?','["A prolonged period of greatly reduced activity and metabolism","Daily migration to warmer oceans","Changing from a mammal into a reptile","Continuous feeding through the night"]'::jsonb,'A prolonged period of greatly reduced activity and metabolism','Hibernation is a seasonal state in which an animal''s activity and metabolic rate fall substantially.',10,2,array['animal behavior'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1434','animals','Classification','easy','classic','What do biologists call an animal that eats both plant and animal matter?','["An omnivore","A herbivore","A carnivore","A decomposer"]'::jsonb,'An omnivore','An omnivore includes both plant and animal foods in its diet.',10,2,array['classification'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
