insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1436','animals','Animal behavior','medium','classic','What is imprinting in animal behavior?','["A rapid form of learning during a sensitive early period","The seasonal replacement of every tooth","A type of migration caused by tides","The formation of a fossil in rock"]'::jsonb,'A rapid form of learning during a sensitive early period','In imprinting, young animals rapidly learn to recognize a parent or other important object during a sensitive period.',10,2,array['animal behavior'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
