insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1440','birds','Feeding','medium','classic','How do flamingos commonly strain small food from shallow water?','["They filter it with specialized bills","They catch it with teeth","They scoop it up with their wings","They inject it with a stinger"]'::jsonb,'They filter it with specialized bills','A flamingo''s bill helps filter small food items such as algae and tiny crustaceans from water.',10,2,array['feeding'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1441','birds','Bird anatomy','easy','classic','How many toes does an ostrich have on each foot?','["Two","Three","Four","Five"]'::jsonb,'Two','An ostrich has two toes on each foot, an adaptation associated with running.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1442','birds','Flight','medium','classic','What is dynamic soaring used by some albatrosses to do?','["Gain energy from wind gradients over the ocean","Hover motionless without moving air","Dive below the sea to breathe","Build nests while flying"]'::jsonb,'Gain energy from wind gradients over the ocean','Albatrosses use dynamic soaring, repeatedly crossing wind layers to travel efficiently over the sea.',10,2,array['flight'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1443','birds','Bird anatomy','medium','classic','What arrangement is called a zygodactyl foot in many parrots?','["Two toes point forward and two point backward","All four toes point forward","Three toes point backward and one forward","The toes are joined into one paddle"]'::jsonb,'Two toes point forward and two point backward','Many parrots have zygodactyl feet, with two toes forward and two backward for grasping.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1444','birds','Flight','medium','classic','Which bird is famous for reaching very high speeds during a hunting dive?','["Peregrine falcon","Common loon","Mute swan","Emperor penguin"]'::jsonb,'Peregrine falcon','A peregrine falcon can reach remarkable speeds while diving toward prey.',10,2,array['flight'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
