insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1446','birds','Feeding','easy','classic','Which bird often wades in shallow water on long legs while hunting?','["Heron","Swift","Woodpecker","Partridge"]'::jsonb,'Heron','Herons use their long legs to wade and catch fish and other prey in shallow water.',10,2,array['feeding'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1447','birds','Bird anatomy','medium','classic','What does a bird''s crop mainly do?','["Temporarily stores food before digestion","Filters salt from seawater","Produces feathers","Pumps air into the heart"]'::jsonb,'Temporarily stores food before digestion','The crop is an expandable part of the digestive tract where food can be stored temporarily.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1448','birds','Bird behavior','medium','classic','Why do many birds gather in flocks?','["Group living can help with vigilance and foraging","It prevents every bird from needing feathers","It turns migration into hibernation","It makes birds unable to communicate"]'::jsonb,'Group living can help with vigilance and foraging','Flocking can provide benefits such as shared predator detection and improved foraging opportunities.',10,2,array['bird behavior'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1449','birds','Flight','medium','classic','What do air sacs do in a bird''s respiratory system?','["Help move air through the lungs","Store food for winter","Replace the bird''s heart","Produce the hard outer shell of an egg"]'::jsonb,'Help move air through the lungs','Air sacs help maintain airflow through the bird''s lungs during breathing.',10,2,array['flight'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1450','birds','Reproduction','easy','classic','What is the main mineral component of most hard bird eggshells?','["Calcium carbonate","Sodium chloride","Silicon dioxide","Iron oxide"]'::jsonb,'Calcium carbonate','Most hard bird eggshells are made largely of calcium carbonate.',10,2,array['reproduction'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1451','birds','Feeding','easy','classic','Which bird uses a strong bill to chisel insects from tree bark?','["Woodpecker","Flamingo","Albatross","Puffin"]'::jsonb,'Woodpecker','Woodpeckers use their bills to probe or chisel into wood in search of insects and other food.',10,2,array['feeding'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1452','birds','Bird behavior','medium','classic','What does a bird''s territorial song commonly help communicate?','["A claim to an area or a mate-attracting signal","The bird''s exact age in years","A request for salt water","A warning that the bird cannot fly"]'::jsonb,'A claim to an area or a mate-attracting signal','Many bird songs help advertise territories and attract mates, although calls also serve other functions.',10,2,array['bird behavior'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1453','birds','Bird anatomy','medium','classic','What is a bird''s cloaca?','["A shared chamber for digestive, urinary, and reproductive openings","A feather used only for steering","A specialized air sac in the wing","A pouch used to carry fish"]'::jsonb,'A shared chamber for digestive, urinary, and reproductive openings','The cloaca is a common exit chamber for the digestive, urinary, and reproductive tracts in birds.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1454','birds','Habitats','easy','classic','Which bird is adapted to plunge into water and catch fish with its large bill pouch?','["Pelican","Goldfinch","Wren","Hoopoe"]'::jsonb,'Pelican','Pelicans use their expandable bill pouches to scoop up fish and water.',10,2,array['habitats'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1455','birds','Conservation','medium','classic','Why can invasive predators threaten ground-nesting island birds?','["The birds may have few defenses against unfamiliar predators","The predators make the islands rotate","The birds lose the ability to lay eggs","The predators remove all oxygen from the air"]'::jsonb,'The birds may have few defenses against unfamiliar predators','Island species can be vulnerable to introduced predators because they evolved without those threats.',10,2,array['conservation'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1456','birds','Migration','medium','classic','What is a major reason some birds migrate between breeding and wintering grounds?','["Seasonal changes in food and breeding conditions","To change from one bird species into another","To avoid ever drinking water","To keep their feathers from growing"]'::jsonb,'Seasonal changes in food and breeding conditions','Migration often lets birds use seasonal food supplies and suitable breeding habitats in different regions.',10,2,array['migration'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1457','nature','Ecology','easy','classic','How is pollen transferred to a flower’s receptive surface?','["The transfer of pollen to a flower''s receptive surface","The release of seeds from a fruit","The evaporation of water from leaves","The breakdown of rock by wind"]'::jsonb,'The transfer of pollen to a flower''s receptive surface','Pollination transfers pollen to a flower''s stigma or other receptive surface, enabling fertilization in many plants.',10,2,array['ecology'],'en',true,'USGS Water Science School and NASA Earth Science — https://www.usgs.gov/special-topics/water-science-school ; https://science.nasa.gov/earth/') on conflict (id) do nothing;
