insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1576','history','World history','medium','classic','Which 1960s movement campaigned for equal civil rights for Black Americans?','["The US Civil Rights Movement","The Meiji Restoration","The Glorious Revolution","The Reconquista"]'::jsonb,'The US Civil Rights Movement','The US Civil Rights Movement sought to end racial segregation and discrimination and secure equal rights.',10,2,array['world history'],'en',true,'Encyclopaedia Britannica History & Society — https://www.britannica.com/browse/History-Society') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1577','technology','Internet','easy','classic','What does DNS do on the internet?','["Translates domain names into network addresses","Encrypts every screen image","Stores a computer''s battery charge","Measures the speed of a keyboard"]'::jsonb,'Translates domain names into network addresses','The Domain Name System helps translate human-readable domain names into internet addresses.',10,2,array['internet'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1578','technology','Web','easy','classic','What does CSS mainly control on a web page?','["Presentation and visual styling","The physical movement of a mouse","The voltage supplied to a monitor","The encryption of every database"]'::jsonb,'Presentation and visual styling','Cascading Style Sheets define presentation features such as colors, spacing, and layout.',10,2,array['web'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1579','technology','Cloud computing','medium','classic','What is cloud computing?','["Using computing services delivered over a network","Storing files only on paper","A weather forecast generated by a thermometer","Running a computer without electricity"]'::jsonb,'Using computing services delivered over a network','Cloud computing provides on-demand computing resources and services over a network, commonly the internet.',10,2,array['cloud computing'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1580','technology','Security','medium','classic','What does encryption do to data?','["Transforms it so it is unreadable without the right key","Deletes every copy permanently","Makes a screen brighter","Converts a file into a printed page"]'::jsonb,'Transforms it so it is unreadable without the right key','Encryption transforms data so that only someone with the appropriate key can read it.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1581','technology','Security','medium','classic','What is a firewall used for in computer security?','["To control network traffic according to rules","To cool a processor with water","To increase a phone''s screen resolution","To store website pictures permanently"]'::jsonb,'To control network traffic according to rules','A firewall monitors and controls incoming or outgoing network traffic based on security rules.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1582','technology','Software','medium','classic','How is software with publicly available, modifiable source code described?','["Software whose source code is available under a license allowing use and modification","Software that can only run without an operating system","Software with no user interface","Software that is always free of copyright"]'::jsonb,'Software whose source code is available under a license allowing use and modification','Open-source licenses make source code available for use, study, modification, and redistribution under stated terms.',10,2,array['software'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1583','technology','Software','easy','classic','What is Git commonly used to track?','["Changes to files in a project over time","The location of a phone in real time","The temperature of a server room","The number of pixels on a display"]'::jsonb,'Changes to files in a project over time','Git is a version-control system that records and manages changes to files.',10,2,array['software'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1584','technology','Data','easy','classic','What kind of code is a QR code?','["A two-dimensional matrix barcode","A spoken password","A type of analog radio wave","A three-dimensional printed map"]'::jsonb,'A two-dimensional matrix barcode','A QR code is a two-dimensional barcode that can encode data for scanning by a camera or reader.',10,2,array['data'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1585','technology','Security','medium','classic','What does two-factor authentication require?','["Two different types of verification factors","Two copies of the same password","Two usernames typed at once","Two internet browsers open together"]'::jsonb,'Two different types of verification factors','Two-factor authentication uses two different factor categories, such as something known and something possessed.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1586','technology','Software','easy','classic','What is an API?','["A defined way for software systems to communicate","A battery used in a camera","A type of computer screen","A paper-only instruction manual"]'::jsonb,'A defined way for software systems to communicate','An application programming interface defines how software components or services can request and exchange information.',10,2,array['software'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1587','technology','Internet','medium','classic','What is a cache in computing?','["A temporary store that can speed up later access","A permanent copy that cannot be changed","A type of network cable connector","A device that measures room humidity"]'::jsonb,'A temporary store that can speed up later access','A cache keeps copies of data likely to be used again so access can be faster.',10,2,array['internet'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1588','technology','Web','easy','classic','What is a browser cookie?','["A small piece of data a website asks a browser to store","A physical key for a server room","A picture format used only for maps","A program that cleans a keyboard"]'::jsonb,'A small piece of data a website asks a browser to store','A web cookie is data stored by a browser on behalf of a website, often to remember state or preferences.',10,2,array['web'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1589','technology','Networks','easy','classic','Bluetooth is commonly used for what kind of connection?','["Short-range wireless communication","Deep-sea fiber-optic cables only","Satellite television broadcasting only","Wired power distribution"]'::jsonb,'Short-range wireless communication','Bluetooth is a short-range wireless technology used to connect devices and exchange data.',10,2,array['networks'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1590','technology','Accessibility','medium','classic','What does alternative text provide for an informative image on a web page?','["A text description that can be conveyed by assistive technology","A larger image file","An automatic color filter","A link that always opens the camera"]'::jsonb,'A text description that can be conveyed by assistive technology','Alternative text conveys the purpose or content of an image to people who cannot see it.',10,2,array['accessibility'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1591','technology','Security','medium','classic','What do we call software designed to harm or misuse a device?','["Software designed to cause harm or perform unwanted actions","A method for repairing a cracked screen","A harmless system font","A cable used to connect a printer"]'::jsonb,'Software designed to cause harm or perform unwanted actions','Malware is software intended to disrupt, damage, spy on, or gain unauthorized access to systems.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1592','technology','Networks','medium','classic','What does a modem commonly do?','["Modulates and demodulates signals for a communications link","Displays web pages without a computer","Stores every file on the internet","Converts keyboard input into printed letters"]'::jsonb,'Modulates and demodulates signals for a communications link','A modem converts signals to enable data communication over a particular transmission medium.',10,2,array['networks'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1593','technology','Data','medium','classic','What does data compression aim to do?','["Represent data using less storage or transmission space","Make every image physically larger","Prevent all edits to a document","Increase the number of colors in a monitor"]'::jsonb,'Represent data using less storage or transmission space','Compression encodes data more compactly to reduce its storage size or transmission requirements.',10,2,array['data'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1594','technology','Security','medium','classic','Why should software updates be installed?','["They can fix security flaws and improve or repair software","They always erase every user file","They replace the need for backups","They make passwords unnecessary"]'::jsonb,'They can fix security flaws and improve or repair software','Updates can correct bugs, patch vulnerabilities, and add or improve software features.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1595','technology','Hardware','easy','classic','What does a GPU mainly accelerate?','["Graphics and other highly parallel computations","The mechanical rotation of a hard drive","The pressure inside a keyboard","The sound made by a microphone"]'::jsonb,'Graphics and other highly parallel computations','A graphics processing unit is designed to handle graphics and other workloads that benefit from parallel processing.',10,2,array['hardware'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1596','technology','Internet','medium','classic','What does a virtual private network commonly create over another network?','["An encrypted connection between a device and a VPN service","A new physical fiber cable under the ocean","A public copy of every private file","A replacement for all computer memory"]'::jsonb,'An encrypted connection between a device and a VPN service','A VPN can create an encrypted tunnel over a network, protecting traffic between a device and the VPN endpoint.',10,2,array['internet'],'en',true,'NIST Computer Security Resource Center glossary and MDN Web Docs — https://csrc.nist.gov/glossary ; https://developer.mozilla.org/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1597','sports','Basketball','easy','classic','How many points is a successful three-point field goal worth in standard basketball rules?','["Three","One","Two","Four"]'::jsonb,'Three','A field goal scored from beyond the three-point line is worth three points under standard basketball rules.',10,2,array['basketball'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1598','sports','Volleyball','medium','classic','In standard indoor volleyball, how many points usually win a set, with a two-point lead required?','["Twenty-five","Fifteen","Twenty-one","Thirty"]'::jsonb,'Twenty-five','Most indoor volleyball sets are played to 25 points and must be won by at least two points; deciding sets differ.',10,2,array['volleyball'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1599','sports','Baseball','easy','classic','How many strikes usually retire a batter in baseball?','["Three","Two","Four","Five"]'::jsonb,'Three','In baseball, a batter is normally out after accumulating three strikes, subject to specific rules.',10,2,array['baseball'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1600','sports','Golf','easy','classic','In golf, what is a birdie?','["One stroke under par on a hole","Two strokes over par on a hole","A hole completed in exactly par","A penalty for hitting a bird"]'::jsonb,'One stroke under par on a hole','A birdie is a score of one stroke under the stated par for a golf hole.',10,2,array['golf'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1601','sports','Athletics','easy','classic','How long is an official marathon race?','["42.195 kilometres","40 kilometres","45 kilometres","50 kilometres"]'::jsonb,'42.195 kilometres','The standard marathon distance is 42.195 kilometres, or 26 miles and 385 yards.',10,2,array['athletics'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
