insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1604','sports','Table tennis','medium','classic','How many points usually win a table-tennis game, provided the player leads by two?','["Eleven","Seven","Fifteen","Twenty-one"]'::jsonb,'Eleven','A table-tennis game is normally played to 11 points, and a player must win by two.',10,2,array['table tennis'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
