insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1612','sports','Cycling','medium','classic','In a road cycling race, what does a peloton refer to?','["The main group of riders","The bicycle''s rear gear","A rider''s water bottle","The final sprint line"]'::jsonb,'The main group of riders','The peloton is the main group of riders in a road race, where drafting can reduce wind resistance.',10,2,array['cycling'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1613','sports','Skating','medium','classic','In figure skating, what does a pair of skaters perform together?','["A routine combining skating elements and choreography","A bicycle road race","A timed swimming relay","A series of basketball free throws"]'::jsonb,'A routine combining skating elements and choreography','Pair skating combines technical elements with choreography performed by two skaters.',10,2,array['skating'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
