insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1615','sports','Tennis','medium','classic','What is the term for a serve that the receiver cannot touch with the racket?','["Ace","Deuce","Volley","Let"]'::jsonb,'Ace','An ace is a legal serve that the receiver does not touch with the racket.',10,2,array['tennis'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1616','sports','Sport safety','easy','classic','What is a common purpose of a warm-up before vigorous exercise?','["Prepare the body gradually for activity","Replace water for the whole day","Guarantee that injury is impossible","Make the muscles stop using oxygen"]'::jsonb,'Prepare the body gradually for activity','A warm-up gradually raises activity and prepares the body for more vigorous movement; it cannot eliminate all injury risk.',10,2,array['sport safety'],'en',true,'Official rules: IFAB, ICC, BWF, FIBA, World Athletics, FIVB — https://www.theifab.com/laws/ ; https://www.icc-cricket.com/about/cricket/rules-and-regulations ; https://corporate.bwfbadminton.com/statutes/ ; https://www.fiba.basketball/documents ; https://worldathletics.org/about-iaaf/documents/book-of-rules ; https://www.fivb.com/volleyball/the-game/official-volleyball-rules/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1617','civics','Institutions','easy','classic','What does separation of powers do in a system of government?','["Divides public authority among different branches","Combines every government role in one office","Transfers every law to private companies","Removes the need for courts"]'::jsonb,'Divides public authority among different branches','Separation of powers distributes government functions among branches to limit concentrated authority.',10,2,array['institutions'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1618','civics','Institutions','easy','classic','What is the main role of an executive branch?','["Carry out and administer laws","Interpret every court judgment","Write all newspaper articles","Count private business profits"]'::jsonb,'Carry out and administer laws','The executive branch administers government and implements laws and policies.',10,2,array['institutions'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1619','civics','Institutions','easy','classic','What is a bill in a legislature?','["A proposal for a new law or a change to a law","A receipt for a tax payment","A final court sentence","A list of voters who have moved"]'::jsonb,'A proposal for a new law or a change to a law','A bill is a proposed law that may be considered and amended by a legislature.',10,2,array['institutions'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1620','civics','Institutions','medium','classic','What is a legislative committee often tasked with doing?','["Examining a subject or proposed bill in detail","Replacing all elected representatives","Issuing private bank loans","Selecting the national anthem by lottery"]'::jsonb,'Examining a subject or proposed bill in detail','Legislative committees can examine bills, gather evidence, and report recommendations to the legislature.',10,2,array['institutions'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1621','civics','Elections','easy','classic','What is a constituency?','["An area represented by an elected official","A group of judges serving one court","A list of laws that have expired","A government building used for storage"]'::jsonb,'An area represented by an elected official','A constituency is a defined area or group whose voters elect a representative.',10,2,array['elections'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1622','civics','Elections','medium','classic','What is a referendum?','["A direct vote by the electorate on a proposal or issue","A private meeting of cabinet ministers","A routine court appeal","A budget report from a central bank"]'::jsonb,'A direct vote by the electorate on a proposal or issue','A referendum lets eligible voters decide directly on a specific public question or proposal.',10,2,array['elections'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1623','civics','Public administration','medium','classic','What is an ombudsman commonly appointed to do?','["Investigate complaints about public administration","Write every law in a country","Manage the national weather service","Set the price of every product"]'::jsonb,'Investigate complaints about public administration','An ombudsman independently investigates complaints about public bodies or services.',10,2,array['public administration'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1624','civics','Public finance','easy','classic','What does a public budget usually set out?','["Planned government income and spending","The private savings of every resident","The daily weather forecast","A list of every court case"]'::jsonb,'Planned government income and spending','A public budget estimates government revenue and authorizes or plans expenditure for a period.',10,2,array['public finance'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1625','civics','Principles','medium','classic','Under the rule of law, what principle applies to people and public authorities?','["Public authorities and people are subject to publicly known laws","Officials may ignore laws whenever they choose","Only visitors must obey laws","Every court case must have the same outcome"]'::jsonb,'Public authorities and people are subject to publicly known laws','The rule of law requires law to govern public power and apply through fair, accountable institutions.',10,2,array['principles'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1626','civics','Systems','medium','classic','What is federalism?','["A system that shares authority between national and regional governments","A system with no local government","A government controlled by a single private company","A voting method that uses only paper ballots"]'::jsonb,'A system that shares authority between national and regional governments','Federalism divides or shares governmental powers between a national level and constituent regions or states.',10,2,array['systems'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1627','civics','Principles','medium','classic','What does transparency in government aim to support?','["Public understanding and scrutiny of decisions","Secrecy about every use of public money","A ban on publishing public records","The removal of all public meetings"]'::jsonb,'Public understanding and scrutiny of decisions','Transparency makes public decisions and information more visible for accountability and civic scrutiny.',10,2,array['principles'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1628','civics','Elections','easy','classic','What is a term of office?','["The period during which a person holds an elected or appointed position","A document proving a person owns a home","The time taken to count one ballot","A rule that prevents a meeting from ending"]'::jsonb,'The period during which a person holds an elected or appointed position','A term of office is the defined period for which a person serves in a position.',10,2,array['elections'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1629','civics','Public administration','medium','classic','What is a civil service?','["A professional public workforce that carries out government administration","A private club for retired judges","A group that writes commercial advertisements","A volunteer team that runs every election"]'::jsonb,'A professional public workforce that carries out government administration','Civil services are professional public-sector organizations that support the administration of government.',10,2,array['public administration'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1630','civics','Principles','medium','classic','What does an independent judiciary help protect?','["Fair adjudication without improper interference","The executive''s control over every verdict","The right to ignore court orders","The secrecy of all public budgets"]'::jsonb,'Fair adjudication without improper interference','Judicial independence helps courts decide cases impartially and free from improper pressure.',10,2,array['principles'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1631','civics','Public participation','easy','classic','What is a public hearing commonly used to do?','["Let people share views or evidence on a proposal","Set the private salaries of every official","Replace the work of a national court","Choose a sports team for a city"]'::jsonb,'Let people share views or evidence on a proposal','A public hearing gives people an opportunity to present views or evidence on a public proposal or issue.',10,2,array['public participation'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1632','civics','Institutions','medium','classic','What does a parliamentary opposition commonly do?','["Scrutinizes the government and presents alternative views","Runs the courts instead of judges","Counts votes after every sports match","Sets interest rates for commercial banks"]'::jsonb,'Scrutinizes the government and presents alternative views','Opposition parties question government actions and offer alternatives in a representative system.',10,2,array['institutions'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1633','civics','Public participation','medium','classic','What is a public consultation?','["A process for inviting views before a decision","A secret vote limited to ministers","A tax paid for public roads","An automatic court judgment"]'::jsonb,'A process for inviting views before a decision','Public consultation gathers views from affected people before or during a policy or decision process.',10,2,array['public participation'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1634','civics','Public finance','medium','classic','Why might a government publish an audit of public spending?','["To provide evidence about how funds were used","To guarantee that no project ever fails","To replace the national budget","To prevent citizens from asking questions"]'::jsonb,'To provide evidence about how funds were used','Public audits examine records and controls to report whether public resources were managed and accounted for.',10,2,array['public finance'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1635','civics','Local government','easy','classic','What is a ward in many local-government systems?','["A smaller area used for local representation or administration","A national border between countries","A branch of the central bank","A unit for measuring rainfall"]'::jsonb,'A smaller area used for local representation or administration','A ward is commonly a local electoral or administrative division within a town or city.',10,2,array['local government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1636','civics','Principles','medium','classic','What is accountability in public service?','["The duty to explain actions and answer for responsibilities","The right to conceal every decision","A method of counting only tax receipts","A rule that cancels public oversight"]'::jsonb,'The duty to explain actions and answer for responsibilities','Accountability means decision-makers must explain their actions and can be held responsible for them.',10,2,array['principles'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1637','economics','Markets','medium','classic','According to the law of supply, what usually happens to quantity supplied when price rises, other things equal?','["It tends to increase","It always falls to zero","It stays fixed for every product","It changes only when taxes disappear"]'::jsonb,'It tends to increase','The law of supply describes a tendency for producers to offer more at higher prices, other things equal.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1638','economics','Markets','easy','classic','What is a budget constraint?','["A limit on choices created by available resources and prices","A rule that prices never change","A tax charged only on savings","A guarantee of unlimited income"]'::jsonb,'A limit on choices created by available resources and prices','A budget constraint shows the combinations a person can afford with limited income and given prices.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1639','economics','Markets','easy','classic','What is a service in economics?','["An activity or benefit provided rather than a physical good","A natural resource before extraction","A tax refunded to a company","A unit used to measure inflation"]'::jsonb,'An activity or benefit provided rather than a physical good','Services are economic activities or benefits that are generally intangible rather than physical goods.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1640','economics','Money','medium','classic','Which is a common function of money?','["A store of value","A guarantee that prices never rise","A replacement for every legal system","A measure of physical distance"]'::jsonb,'A store of value','Money commonly serves as a medium of exchange, a unit of account, and a store of value.',10,2,array['money'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1641','economics','Banking','medium','classic','What is a central bank commonly responsible for?','["Conducting monetary policy and supporting the financial system","Setting the menu prices of restaurants","Issuing every private company''s shares","Choosing the winners of national elections"]'::jsonb,'Conducting monetary policy and supporting the financial system','Central banks commonly conduct monetary policy and support financial and payment-system stability.',10,2,array['banking'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1642','economics','Banking','easy','classic','What does a borrower pay as the cost of taking a loan?','["The cost paid for borrowing money","A tax paid only on imported fruit","The number of bank branches in a city","A reward that cancels the original debt"]'::jsonb,'The cost paid for borrowing money','Interest is the charge for borrowing money, usually expressed as a rate over time.',10,2,array['banking'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1643','economics','Banking','medium','classic','What is compound interest?','["Interest calculated on principal and previously accumulated interest","Interest paid only once on a loan''s final day","A tax on every cash purchase","A fee for exchanging paper money"]'::jsonb,'Interest calculated on principal and previously accumulated interest','With compound interest, interest is earned or charged on the principal and on prior accumulated interest.',10,2,array['banking'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1644','economics','Markets','medium','classic','What is a negative externality?','["A cost imposed on people not directly involved in a transaction","A discount given to every buyer","A benefit that belongs only to the producer","A change in the spelling of a price"]'::jsonb,'A cost imposed on people not directly involved in a transaction','A negative externality is a cost borne by a third party, such as pollution affecting nearby residents.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1645','economics','Markets','medium','classic','In economics, what is a monopoly?','["A market dominated by one seller with no close substitute","A market with thousands of identical sellers","A government budget with no taxes","A store that accepts only coins"]'::jsonb,'A market dominated by one seller with no close substitute','A monopoly is a market structure in which one seller has substantial control and buyers lack close alternatives.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1646','economics','Markets','medium','classic','What does comparative advantage depend on?','["A lower opportunity cost of producing something","Having the largest population","Charging the highest possible price","Producing every good with no resources"]'::jsonb,'A lower opportunity cost of producing something','Comparative advantage arises when a producer can make a good at a lower opportunity cost than another producer.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1647','economics','National accounts','medium','classic','Why are intermediate goods generally excluded from a country''s GDP calculation?','["To avoid counting the same production more than once","They are always imported","They have no market price","They are produced only by governments"]'::jsonb,'To avoid counting the same production more than once','Excluding intermediate inputs helps avoid double counting the value of goods incorporated into final output.',10,2,array['national accounts'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1648','economics','National accounts','medium','classic','What does real GDP adjust for when comparing output over time?','["Changes in prices","Changes in a country''s borders","The number of banknotes printed","The age of the population only"]'::jsonb,'Changes in prices','Real GDP uses price adjustments to distinguish changes in production from changes in the price level.',10,2,array['national accounts'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1649','economics','National accounts','easy','classic','What does a currency exchange rate express?','["The price of one currency in terms of another","The height of a country''s mountains","The number of products in a store","The amount of rainfall in a year"]'::jsonb,'The price of one currency in terms of another','An exchange rate states how much of one currency can be exchanged for another.',10,2,array['national accounts'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1650','economics','Labor','medium','classic','What is a minimum wage?','["A legally established lowest pay rate for covered work","The average price of a household meal","A bonus paid only to managers","A limit on the number of bank accounts"]'::jsonb,'A legally established lowest pay rate for covered work','A minimum wage sets a legal floor for the pay of workers covered by the relevant rules.',10,2,array['labor'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1651','economics','Prices','medium','classic','What does a consumer price index commonly track?','["Changes in prices for a selected basket of consumer goods and services","The number of products made by one factory","The total value of every house in a country","The wages of only one profession"]'::jsonb,'Changes in prices for a selected basket of consumer goods and services','A consumer price index measures changes in the prices of a representative basket over time.',10,2,array['prices'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1652','economics','Public finance','medium','classic','What is a progressive income tax?','["A tax system with higher marginal rates at higher income levels","A tax that charges the same total amount to everyone","A tax applied only to exports","A tax that falls whenever income rises"]'::jsonb,'A tax system with higher marginal rates at higher income levels','A progressive income tax generally applies higher marginal rates as taxable income rises.',10,2,array['public finance'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1653','economics','Public finance','easy','classic','What term describes financial support that can lower the cost of a good or service?','["Financial support from a government or other institution","A penalty for buying a local product","A loan that never has to be repaid in every case","A type of currency exchange rate"]'::jsonb,'Financial support from a government or other institution','A subsidy is financial assistance that can lower costs or support an activity or group.',10,2,array['public finance'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1654','economics','Production','medium','classic','What is a production possibility frontier used to illustrate?','["Possible output combinations given resources and technology","The exact weather in every production region","A list of all government employees","The price of one share on a stock exchange"]'::jsonb,'Possible output combinations given resources and technology','A production possibility frontier illustrates feasible combinations of output with available resources and technology.',10,2,array['production'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1655','economics','Markets','medium','classic','What is price elasticity of demand?','["How responsive quantity demanded is to a change in price","How quickly money is printed","The weight of a product''s packaging","How many sellers are registered in a city"]'::jsonb,'How responsive quantity demanded is to a change in price','Price elasticity of demand measures the responsiveness of quantity demanded to a change in price.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1656','economics','Trade','medium','classic','What is a trade surplus?','["A period when exports exceed imports in value","A market where no goods are exchanged","A tax charged on local wages","A bank account with no deposits"]'::jsonb,'A period when exports exceed imports in value','A trade surplus occurs when the value of exports exceeds the value of imports over a period.',10,2,array['trade'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1657','music','Notation','easy','classic','In common time, how many quarter-note beats does a half note usually last?','["Two","One","Three","Four"]'::jsonb,'Two','A half note normally lasts two quarter-note beats in common time.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1658','music','Notation','medium','classic','What does a fermata sign tell a performer to do?','["Hold a note or rest longer than its written value","Play the next note an octave lower","Repeat the entire piece twice","Stop the music permanently"]'::jsonb,'Hold a note or rest longer than its written value','A fermata indicates that a note or rest is sustained beyond its usual written duration.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1659','music','Notation','medium','classic','What does a key signature show in standard staff notation?','["Which notes are regularly sharpened or flattened","The names of the performers","The exact length of every song","The seating plan of an orchestra"]'::jsonb,'Which notes are regularly sharpened or flattened','A key signature displays sharps or flats that apply regularly to notes in a piece.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1660','music','Notation','medium','classic','Which note line does the treble clef identify as G?','["The second line from the bottom","The bottom line","The middle line","The top line"]'::jsonb,'The second line from the bottom','The treble clef curls around the second line from the bottom, marking it as G.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1661','music','Notation','medium','classic','Which two notes does the bass clef''s pair of dots surround?','["F on the second line from the top","C on the middle line","A on the top line","E on the bottom line"]'::jsonb,'F on the second line from the top','The bass clef''s dots sit above and below the F line, the second line from the top.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1662','music','Performance','easy','classic','What does legato ask a musician to do?','["Play notes smoothly connected","Make every note as short as possible","Gradually increase the volume","Pause after every beat"]'::jsonb,'Play notes smoothly connected','Legato indicates a smooth, connected manner of performance.',10,2,array['performance'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1663','music','Performance','easy','classic','What does staccato usually indicate?','["Notes should be short and detached","Notes should be held without limit","The tempo must double","The melody should be sung by a choir"]'::jsonb,'Notes should be short and detached','Staccato marks notes to be performed in a short, detached manner.',10,2,array['performance'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1664','music','Dynamics','easy','classic','When music builds to a crescendo, how does its volume change?','["Gradually get louder","Gradually get softer","Repeat the passage exactly","Play without a steady beat"]'::jsonb,'Gradually get louder','Crescendo directs a gradual increase in loudness.',10,2,array['dynamics'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1665','music','Dynamics','easy','classic','What does decrescendo mean?','["Gradually get softer","Gradually get louder","Change to a different instrument","Play each note twice"]'::jsonb,'Gradually get softer','Decrescendo directs a gradual decrease in loudness.',10,2,array['dynamics'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1666','music','Rhythm','medium','classic','What is syncopation?','["Emphasizing unexpected or normally weak beats","Playing every note at the same pitch","Tuning an instrument to a new key","Silencing the melody while keeping the harmony"]'::jsonb,'Emphasizing unexpected or normally weak beats','Syncopation places accents on unexpected parts of a beat or measure.',10,2,array['rhythm'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1667','music','Harmony','medium','classic','What is the tonic in a musical key?','["The first scale degree and tonal center","The fifth note of every melody only","The loudest instrument in an ensemble","The final barline of a score"]'::jsonb,'The first scale degree and tonal center','The tonic is the first scale degree and often functions as the central pitch of a key.',10,2,array['harmony'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1668','music','Harmony','medium','classic','What is the dominant scale degree in a major or minor key?','["The fifth degree","The second degree","The fourth degree","The seventh degree only"]'::jsonb,'The fifth degree','The dominant is the fifth scale degree and often creates a sense of movement toward the tonic.',10,2,array['harmony'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1669','music','Melody','medium','classic','What is a musical sequence?','["A pattern repeated at a different pitch level","A list of instruments in alphabetical order","A period of silence before a concert","A melody played only on percussion"]'::jsonb,'A pattern repeated at a different pitch level','A sequence repeats a melodic or harmonic pattern at a different pitch level.',10,2,array['melody'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1670','music','Ensembles','easy','classic','What is call and response in music?','["A musical phrase is answered by another phrase or group","Every musician plays in complete silence","A singer changes instruments after each note","A conductor counts the audience members"]'::jsonb,'A musical phrase is answered by another phrase or group','Call and response is a pattern in which one musical voice or group is answered by another.',10,2,array['ensembles'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1671','music','Pitch','medium','classic','In twelve-tone equal temperament, what is a semitone?','["The smallest interval between adjacent notes","An interval of exactly one octave","A note played without rhythm","A group of twelve simultaneous instruments"]'::jsonb,'The smallest interval between adjacent notes','A semitone is the interval between adjacent pitches in the twelve-tone equal-tempered scale.',10,2,array['pitch'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
