insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1717','braille','Braille basics','easy','classic','How are the six dots in a standard Braille cell arranged?','["In two columns of three dots","In one row of six dots","In three columns of two dots","In a circle around a center dot"]'::jsonb,'In two columns of three dots','A standard six-dot Braille cell has two columns with three dot positions in each column.',10,2,array['braille basics'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1718','braille','Braille basics','easy','classic','In a standard six-dot Braille cell, where is dot 1?','["At the upper left","At the lower left","At the upper right","At the lower right"]'::jsonb,'At the upper left','Braille dots 1, 2, and 3 are arranged from top to bottom in the left column.',10,2,array['braille basics'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1719','braille','Braille basics','easy','classic','Which dots form the right-hand column of a standard Braille cell?','["Dots 4, 5, and 6","Dots 1, 2, and 3","Dots 1, 4, and 5","Dots 2, 3, and 6"]'::jsonb,'Dots 4, 5, and 6','Dots 4, 5, and 6 are arranged from top to bottom in the right column.',10,2,array['braille basics'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1720','braille','Braille tools','medium','classic','What does a refreshable Braille display use to form changing characters?','["Small pins that rise and lower","Ink sprayed onto paper","A rotating set of printed cards","A speaker cone that draws letters"]'::jsonb,'Small pins that rise and lower','A refreshable Braille display raises and lowers pins to present changing Braille characters.',10,2,array['braille tools'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1721','braille','Braille tools','medium','classic','How does a Perkins-style Braille writer usually enter a six-dot cell?','["By pressing a combination of dot keys","By tracing letters with a mouse","By typing a full sentence on one key","By scanning printed ink with a camera"]'::jsonb,'By pressing a combination of dot keys','A Braille writer has keys corresponding to the six dot positions, allowing dots to be entered together.',10,2,array['braille tools'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1722','braille','Braille literacy','medium','classic','What is contracted Braille designed to do?','["Use approved contractions to represent text more compactly","Replace raised dots with color","Translate every language into speech automatically","Remove spaces between all words"]'::jsonb,'Use approved contractions to represent text more compactly','Contracted Braille uses signs that represent letter groups or words to make reading and writing more compact.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1723','braille','Braille literacy','medium','classic','What does uncontracted literary Braille generally represent?','["Text with letters written without word contractions","Only numbers and mathematical signs","A picture with no language","Speech sounds stored as audio"]'::jsonb,'Text with letters written without word contractions','Uncontracted Braille represents text without using the word and letter-group contractions found in contracted forms.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1724','braille','Braille literacy','medium','classic','In UEB, what is the purpose of the number sign before a numeral sequence?','["It indicates that following letter-shaped cells are being used as numbers","It marks the end of a paragraph","It means the next word is a person''s name","It tells a reader to turn the page"]'::jsonb,'It indicates that following letter-shaped cells are being used as numbers','In Unified English Braille, the numeric indicator signals that following a–j patterns are being read as digits.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1725','braille','Braille literacy','medium','classic','What does a capital indicator in literary Braille signal?','["The following letter or letters should be read as uppercase","The next cell is a punctuation mark","The page should be read from right to left","The next word is written in another language"]'::jsonb,'The following letter or letters should be read as uppercase','A capitalization indicator marks the following letter or sequence as uppercase under the code''s rules.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1726','braille','Braille reading','easy','classic','In which direction is a standard line of English Braille read?','["From left to right","From right to left","From top to bottom only","In a spiral from the center"]'::jsonb,'From left to right','English Braille is read from left to right across the line, like standard English print.',10,2,array['braille reading'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1727','braille','Braille writing','medium','classic','When using a traditional slate and stylus, in which direction is the text commonly written on the reverse side of the paper?','["From right to left","From left to right","From bottom to top","In a circle"]'::jsonb,'From right to left','With a conventional slate and stylus, the writer punches reversed cells from right to left so they read correctly when the paper is turned over.',10,2,array['braille writing'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1728','braille','Braille literacy','easy','classic','What makes Braille characters readable by touch?','["Raised dot patterns","Different printed colors","Scented ink","Magnetic sounds"]'::jsonb,'Raised dot patterns','Braille is a tactile writing system in which raised dots can be read by touch.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1729','braille','Braille literacy','medium','classic','Is Braille itself a spoken language?','["No, it is a tactile code used to represent written language","Yes, it is spoken only by computers","Yes, it is a language with no written form","No, it is a type of musical instrument"]'::jsonb,'No, it is a tactile code used to represent written language','Braille is a writing system or code; it represents languages rather than being a language by itself.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1730','braille','Braille literacy','medium','classic','What is Braille music notation used to represent?','["Musical information such as notes and rhythms","Only the names of music venues","The volume setting on a radio","A map of an orchestra stage"]'::jsonb,'Musical information such as notes and rhythms','Braille music notation is a specialized code for reading and writing musical information by touch.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1731','braille','Braille basics','easy','classic','How are dot positions numbered in the left column of a six-dot cell?','["From 1 at the top to 3 at the bottom","From 3 at the top to 1 at the bottom","From 4 at the top to 6 at the bottom","From 6 at the top to 4 at the bottom"]'::jsonb,'From 1 at the top to 3 at the bottom','The left-column dots are numbered 1 at the top, 2 in the middle, and 3 at the bottom.',10,2,array['braille basics'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1732','braille','Braille tools','medium','classic','What is the usual purpose of a Braille label on a household item?','["To let a reader identify information by touch","To make the item produce speech","To change the item''s color","To prevent the item from being opened"]'::jsonb,'To let a reader identify information by touch','A Braille label makes written information on an item accessible by touch.',10,2,array['braille tools'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1733','braille','Braille literacy','medium','classic','Why can punctuation signs matter in Braille just as they do in print?','["They help show sentence structure and meaning","They always identify the writer''s age","They replace every letter in a word","They determine the paper''s thickness"]'::jsonb,'They help show sentence structure and meaning','Punctuation helps a reader understand sentence boundaries, questions, quotations, and other aspects of written meaning.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1734','braille','Braille tools','medium','classic','What is one advantage of a refreshable Braille display connected to a computer?','["It can present changing text from the computer","It prints permanent ink on every page","It automatically corrects every written fact","It enlarges the computer monitor physically"]'::jsonb,'It can present changing text from the computer','A refreshable display can render changing screen text as tactile Braille rather than requiring a separate embossed page for each screen.',10,2,array['braille tools'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1735','braille','Braille literacy','medium','classic','What is a Braille contraction?','["A sign that represents a letter group or word","A raised dot that means a page is damaged","A device that stores a Braille book","A method for making print smaller"]'::jsonb,'A sign that represents a letter group or word','Braille contractions use one or more signs to represent common letter groups or whole words.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1736','braille','Braille accessibility','easy','classic','Which sense is primarily used to read embossed Braille on paper?','["Touch","Smell","Taste","Balance"]'::jsonb,'Touch','Readers use touch, commonly their fingertips, to perceive the raised-dot patterns of embossed Braille.',10,2,array['braille accessibility'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1737','management','Planning','medium','classic','Which sequence of project tasks determines the shortest possible completion time?','["The longest linked sequence of tasks that determines the minimum completion time","A list of tasks that can all be skipped","The project''s spending limit","A chart showing only staff birthdays"]'::jsonb,'The longest linked sequence of tasks that determines the minimum completion time','The critical path is the longest sequence of dependent activities and determines the earliest possible project finish.',10,2,array['planning'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1738','management','Planning','easy','classic','What does a Gantt chart commonly display?','["Project tasks along a timeline","The structure of a company''s bank account","A list of customer complaints by color","The exact wording of every contract"]'::jsonb,'Project tasks along a timeline','A Gantt chart shows scheduled activities as bars across a timeline.',10,2,array['planning'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1739','management','Teams','medium','classic','In a RACI chart, what does the letter A usually stand for?','["Accountable","Available","Audited","Assigned twice"]'::jsonb,'Accountable','RACI commonly expands to Responsible, Accountable, Consulted, and Informed.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1740','management','Project delivery','medium','classic','What project-management term describes uncontrolled growth in requirements?','["Uncontrolled growth in project requirements","A planned reduction in project cost","A method for assigning office desks","A scheduled review of completed work"]'::jsonb,'Uncontrolled growth in project requirements','Scope creep is the gradual, uncontrolled expansion of a project''s requirements or deliverables.',10,2,array['project delivery'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1741','management','Project delivery','medium','classic','What does an agile project approach generally emphasize?','["Iterative delivery and feedback","A single unchangeable plan with no reviews","Avoiding communication with users","Finishing documentation before any work begins"]'::jsonb,'Iterative delivery and feedback','Agile approaches emphasize short cycles, collaboration, feedback, and adapting plans as learning occurs.',10,2,array['project delivery'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1742','management','Quality','medium','classic','What does the Plan-Do-Check-Act cycle support?','["Iterative testing and improvement of a process","A rule that prevents measurement","A method for hiding project risks","A one-time budget approval"]'::jsonb,'Iterative testing and improvement of a process','Plan-Do-Check-Act is a repeated cycle used to test changes and improve processes.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1743','management','Problem solving','medium','classic','What is root-cause analysis intended to identify?','["Underlying reasons a problem occurred","The person who should always be blamed","The price of replacing every tool","The first item on a meeting agenda"]'::jsonb,'Underlying reasons a problem occurred','Root-cause analysis seeks the underlying causes of a problem so corrective actions can address them.',10,2,array['problem solving'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1744','management','Risk','easy','classic','What is a contingency plan prepared to provide?','["A prepared response for a possible future event","A record of tasks already finished","A list of routine office supplies","A method for setting product colors"]'::jsonb,'A prepared response for a possible future event','A contingency plan describes actions to take if an identified risk or unexpected event occurs.',10,2,array['risk'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1745','management','Communication','easy','classic','What is the main purpose of a meeting agenda?','["To outline topics and guide the meeting","To record every employee''s salary","To replace all meeting discussion","To guarantee that no decision is needed"]'::jsonb,'To outline topics and guide the meeting','An agenda lists the topics and intended order or goals for a meeting.',10,2,array['communication'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1746','management','Project delivery','medium','classic','What is a project baseline?','["An approved reference plan used to compare actual progress","A list of every possible supplier","The final invoice from a contractor","A type of team-building exercise"]'::jsonb,'An approved reference plan used to compare actual progress','A baseline is an approved plan or set of measures against which project performance can be compared.',10,2,array['project delivery'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1747','management','Risk','medium','classic','What does risk mitigation aim to do?','["Reduce the likelihood or impact of a risk","Guarantee that no uncertain event can occur","Transfer every task to a customer","Increase the project''s uncertainty"]'::jsonb,'Reduce the likelihood or impact of a risk','Risk mitigation selects actions intended to lower a risk''s probability or consequences.',10,2,array['risk'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1748','management','Quality','medium','classic','What is quality assurance mainly concerned with?','["Processes intended to help meet quality requirements","Counting only products that failed","Choosing the company''s logo","Setting the selling price of every product"]'::jsonb,'Processes intended to help meet quality requirements','Quality assurance focuses on the processes used to provide confidence that quality requirements will be met.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1749','management','Quality','medium','classic','What is a bottleneck in a workflow?','["A constrained step that limits overall throughput","The fastest step in every process","A type of performance bonus","A process with no inputs"]'::jsonb,'A constrained step that limits overall throughput','A bottleneck is a constraint whose limited capacity slows the flow of the whole process.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1750','management','Teams','easy','classic','What makes feedback constructive?','["It is specific, respectful, and focused on useful improvement","It attacks a person''s character","It avoids describing any behavior","It is delivered only as a rumor"]'::jsonb,'It is specific, respectful, and focused on useful improvement','Constructive feedback describes observable behavior and offers respectful guidance for improvement.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1751','management','Teams','medium','classic','What does psychological safety help team members feel able to do?','["Ask questions and raise concerns without undue fear","Avoid sharing any information","Agree with every idea automatically","Skip all project responsibilities"]'::jsonb,'Ask questions and raise concerns without undue fear','Psychological safety supports interpersonal risk-taking such as asking questions, admitting mistakes, and raising concerns.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1752','management','Planning','medium','classic','What does a project milestone represent?','["A significant checkpoint or event in the project","A small daily expense","A job title on an organization chart","The number of people at a meeting"]'::jsonb,'A significant checkpoint or event in the project','A milestone marks a significant event or checkpoint, rather than a task with a duration.',10,2,array['planning'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1753','management','Change management','medium','classic','What is a change impact assessment used to consider?','["How a proposed change may affect people, processes, and systems","The weather during a project launch","Only the font in a presentation","Whether every employee can use the same desk"]'::jsonb,'How a proposed change may affect people, processes, and systems','A change impact assessment identifies affected groups and possible operational consequences of a proposed change.',10,2,array['change management'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1754','management','Decision making','medium','classic','Why might a manager use a decision log?','["To record key decisions, reasons, and owners","To store passwords in plain view","To replace every project plan","To count the number of emails sent"]'::jsonb,'To record key decisions, reasons, and owners','A decision log records what was decided, why, by whom, and when.',10,2,array['decision making'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1755','management','Vendor management','medium','classic','What does a service-level agreement usually define?','["Expected service standards and how they will be measured","The number of holidays in a school year","The colors used on a company''s website","The maximum size of a customer order"]'::jsonb,'Expected service standards and how they will be measured','A service-level agreement documents agreed service expectations, responsibilities, and measures.',10,2,array['vendor management'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1756','management','Learning','medium','classic','What does a lessons-learned register capture?','["Useful knowledge and experience from a project for future work","Only the names of people who attended one meeting","A list of unapproved expenses","The weather during each workday"]'::jsonb,'Useful knowledge and experience from a project for future work','A lessons-learned register records insights that can improve later projects and organizational practice.',10,2,array['learning'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1757','business','Finance','easy','classic','What is cash flow?','["Money moving into and out of a business","The total number of products in a catalog","The amount of tax on a single import","The brand name printed on a receipt"]'::jsonb,'Money moving into and out of a business','Cash flow tracks cash and cash-equivalent receipts and payments over a period.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1758','business','Finance','medium','classic','What is a fixed cost in a business?','["A cost that does not change directly with short-term output","A cost that rises by exactly one unit for each sale","A customer''s unpaid invoice","A tax that applies only to exports"]'::jsonb,'A cost that does not change directly with short-term output','Fixed costs generally remain stable over a relevant range of activity in the short term.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1759','business','Finance','medium','classic','What is a variable cost?','["A cost that changes with the level of activity or output","A cost that is always zero","A permanent business name","A tax charged only on profit"]'::jsonb,'A cost that changes with the level of activity or output','Variable costs tend to increase or decrease as production or sales activity changes.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1760','business','Finance','medium','classic','What is a business''s break-even point?','["The level where total revenue equals total costs","The point when every employee takes a break","The day a company changes its logo","The amount of money in a customer''s wallet"]'::jsonb,'The level where total revenue equals total costs','At break-even, total revenue equals total costs, so profit is zero before considering other factors.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1761','business','Customers','medium','classic','What does customer retention measure?','["A business''s ability to keep customers over time","The number of products returned to a factory","The amount of cash held in a safe","The length of a company''s legal name"]'::jsonb,'A business''s ability to keep customers over time','Customer retention describes how well a business keeps customers over a period.',10,2,array['customers'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1762','business','Strategy','medium','classic','What are economies of scale?','["Lower average costs that can result as production expands","A rule that every firm must sell the same quantity","A method for measuring a company''s office floor","A guarantee that demand always increases"]'::jsonb,'Lower average costs that can result as production expands','Economies of scale occur when average cost falls as output grows, often due to spreading fixed costs or specialization.',10,2,array['strategy'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1763','business','Law and ownership','medium','classic','What does a patent generally protect?','["A qualifying invention for a limited period under law","A company''s daily cash balance","A customer''s private shopping list","A business''s slogan in every country automatically"]'::jsonb,'A qualifying invention for a limited period under law','A patent gives defined rights over a qualifying invention for a limited term, subject to applicable law.',10,2,array['law and ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1764','business','Law and ownership','medium','classic','What does a trademark primarily identify or distinguish?','["The source of particular goods or services","The chemical makeup of a product","The date a company files its taxes","The weight of a parcel"]'::jsonb,'The source of particular goods or services','A trademark helps distinguish one business''s goods or services from those of others.',10,2,array['law and ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1765','business','Law and ownership','medium','classic','What does copyright protect?','["Original works of authorship expressed in a tangible form","Every idea that has never been discussed","A company''s right to set national tax rates","The ownership of a natural language"]'::jsonb,'Original works of authorship expressed in a tangible form','Copyright protects qualifying original expression, such as writing, music, and artwork, subject to legal limits.',10,2,array['law and ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1766','business','Operations','medium','classic','What is it called when a business hires an outside provider to perform an activity?','["Hiring an outside provider to perform a business activity","Moving every customer into a company office","Selling shares only to employees","Using only materials made by the business"]'::jsonb,'Hiring an outside provider to perform a business activity','Outsourcing obtains a product or service from an external provider rather than performing it in-house.',10,2,array['operations'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1767','business','Business models','medium','classic','What is a subscription business model?','["Customers pay repeatedly for ongoing access or service","Customers pay only after returning every item","A company sells one product exactly once","A firm gives away all services without funding"]'::jsonb,'Customers pay repeatedly for ongoing access or service','Subscription models charge recurring payments for continued access to a product or service.',10,2,array['business models'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1768','business','Finance','medium','classic','What does gross margin compare?','["Revenue remaining after cost of goods sold, relative to revenue","Cash in a bank account and cash in a drawer","The number of customers and the number of suppliers","Interest paid and taxes collected"]'::jsonb,'Revenue remaining after cost of goods sold, relative to revenue','Gross margin is commonly calculated as revenue minus cost of goods sold, divided by revenue.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1769','business','Customers','medium','classic','What is a sales funnel used to describe?','["Stages a prospective customer may pass through before purchase","The route taken by a delivery truck only","A type of employee performance review","The steps used to audit a factory machine"]'::jsonb,'Stages a prospective customer may pass through before purchase','A sales funnel models stages such as awareness, consideration, and purchase in a customer journey.',10,2,array['customers'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1770','business','Operations','medium','classic','What is a value chain?','["Activities through which a business creates and delivers value","A list of every company on a stock exchange","A delivery route with no stops","A chain used to secure a warehouse door"]'::jsonb,'Activities through which a business creates and delivers value','A value chain examines linked activities that contribute to creating, delivering, and supporting a product or service.',10,2,array['operations'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1771','business','Ethics','medium','classic','What does a business code of ethics provide?','["Guidance on expected conduct and values","A guarantee that no customer will ever complain","A list of passwords for company systems","A formula for setting the exchange rate"]'::jsonb,'Guidance on expected conduct and values','A code of ethics sets principles and expectations for conduct within an organization.',10,2,array['ethics'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1772','business','Strategy','medium','classic','What is market segmentation?','["Dividing a broader market into groups with shared characteristics","Setting one identical price for every product","Merging all suppliers into a single company","Measuring the distance from a shop to a warehouse"]'::jsonb,'Dividing a broader market into groups with shared characteristics','Market segmentation divides a broad market into groups with shared needs, traits, or behaviors.',10,2,array['strategy'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1773','business','Strategy','medium','classic','What does diversification mean for a business?','["Expanding into different products, markets, or activities","Selling only one item to one customer","Eliminating all suppliers","Changing the business''s legal name every year"]'::jsonb,'Expanding into different products, markets, or activities','Diversification spreads business activity across different products, customers, markets, or investments.',10,2,array['strategy'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1774','business','Business models','medium','classic','What is a franchise arrangement?','["A business model in which a franchisee operates under a franchisor''s system and brand","A government tax on every shop","A contract that transfers all customer rights","A rule that makes a company a nonprofit"]'::jsonb,'A business model in which a franchisee operates under a franchisor''s system and brand','Franchising lets an independent operator use a franchisor''s brand and business system under an agreement.',10,2,array['business models'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1775','business','Start-ups','medium','classic','What support does a business incubator commonly offer early-stage ventures?','["Mentoring and access to business resources","A guarantee of profit in the first month","An exemption from every law","A permanent ban on outside investment"]'::jsonb,'Mentoring and access to business resources','Business incubators commonly support early-stage firms with mentoring, networks, and shared resources; services vary by program.',10,2,array['start-ups'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1776','business','Strategy','medium','classic','What does a business plan normally describe?','["Goals, strategy, operations, and financial expectations","Only the colors used in the company logo","A list of every product sold by competitors","The exact result of every future decision"]'::jsonb,'Goals, strategy, operations, and financial expectations','A business plan outlines objectives and how a business intends to operate and finance its activities.',10,2,array['strategy'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1777','accounting','Bookkeeping','medium','classic','What is a trial balance used to do?','["List ledger account balances to check debit and credit totals","Guarantee that no accounting error exists","Replace all source documents","Set the market price of company shares"]'::jsonb,'List ledger account balances to check debit and credit totals','A trial balance lists ledger balances and checks whether total debits equal total credits; equality does not prove every error is absent.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1778','accounting','Bookkeeping','easy','classic','What is a journal in accounting?','["A record where transactions are first entered chronologically","A list of a company''s advertisements","A report of future weather","A catalogue of customer birthdays"]'::jsonb,'A record where transactions are first entered chronologically','An accounting journal records transactions in date order before or as they are posted to ledgers.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1779','accounting','Bookkeeping','easy','classic','What does a chart of accounts provide?','["An organized list of accounts used by an entity","A map of the company''s office buildings","A schedule of employee holidays","A collection of invoices from one supplier"]'::jsonb,'An organized list of accounts used by an entity','A chart of accounts names and organizes the accounts used to record financial activity.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1780','accounting','Controls','medium','classic','What accounting process compares cash records with a bank statement?','["A comparison of accounting cash records with a bank statement","A method for calculating employee vacations","A list of customers who have paid in coins","A budget for opening a new bank"]'::jsonb,'A comparison of accounting cash records with a bank statement','A bank reconciliation identifies and explains differences between an entity''s cash records and the bank''s records.',10,2,array['controls'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1781','accounting','Statements','medium','classic','What does a cash flow statement summarize?','["Cash inflows and outflows over a reporting period","Only the value of buildings on one date","The number of products in a warehouse","The personal spending of every employee"]'::jsonb,'Cash inflows and outflows over a reporting period','A cash flow statement reports cash flows, commonly classified as operating, investing, and financing activities.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1782','accounting','Equity','medium','classic','What are retained earnings?','["Accumulated profits kept in the business, less distributions and other adjustments","Amounts customers still owe","Cash borrowed from a supplier","The cost of every product sold in one day"]'::jsonb,'Accumulated profits kept in the business, less distributions and other adjustments','Retained earnings represent accumulated net income retained in equity, adjusted for distributions and other items.',10,2,array['equity'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1783','accounting','Entries','medium','classic','What are closing entries used for at the end of an accounting period?','["Transfer temporary account balances into permanent accounts","Record the opening hours of a shop","Change every asset into cash","Reconcile a company''s logo with its trademark"]'::jsonb,'Transfer temporary account balances into permanent accounts','Closing entries reset temporary revenue and expense accounts and transfer their net result to equity.',10,2,array['entries'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1784','accounting','Accruals','medium','classic','How is a payment made before its related benefit is used classified?','["A payment made before the related benefit is consumed","A bill received after a service is used","A cash sale that has not occurred","A loan that has been forgiven"]'::jsonb,'A payment made before the related benefit is consumed','A prepaid expense is initially recorded as an asset when payment precedes the related use or benefit.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1785','accounting','Accruals','medium','classic','What accounting term describes a cost incurred but not yet paid?','["A cost recognized before it has been paid","A customer payment received before a sale","A product returned to a supplier","A long-term investment that earns a dividend"]'::jsonb,'A cost recognized before it has been paid','An accrued expense is recognized when incurred even though payment will occur later.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1786','accounting','Inventory','medium','classic','What does FIFO mean as an inventory cost-flow assumption?','["First in, first out","Final invoice, final order","Fixed interest, fixed output","Financial information for operations"]'::jsonb,'First in, first out','FIFO assumes that the earliest costs are assigned to goods sold first, subject to the applicable accounting framework.',10,2,array['inventory'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1787','accounting','Analysis','medium','classic','What is the current ratio commonly calculated as?','["Current assets divided by current liabilities","Revenue divided by long-term debt","Cash divided by yearly sales only","Profit divided by the number of employees"]'::jsonb,'Current assets divided by current liabilities','The current ratio is commonly calculated by dividing current assets by current liabilities.',10,2,array['analysis'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1788','accounting','Assets','medium','classic','What is goodwill in financial reporting commonly associated with?','["An acquired business''s value beyond identifiable net assets","A charitable donation recorded as inventory","A company''s daily cash register total","A guarantee that future profit is certain"]'::jsonb,'An acquired business''s value beyond identifiable net assets','Goodwill can arise in a business combination when consideration exceeds the fair value of identifiable net assets acquired.',10,2,array['assets'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1789','accounting','Assets','medium','classic','What is a capital expenditure?','["Spending to acquire or improve a long-term asset","A routine payment for a monthly phone bill","A cash refund from a customer","A dividend paid to a shareholder"]'::jsonb,'Spending to acquire or improve a long-term asset','Capital expenditure generally creates or improves a long-term asset rather than paying an ordinary period expense.',10,2,array['assets'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1790','accounting','Controls','medium','classic','What is an internal control in accounting?','["A process designed to support reliable reporting and safeguard resources","A tax rate set by another country","A marketing slogan printed on a receipt","A forecast that is guaranteed to be exact"]'::jsonb,'A process designed to support reliable reporting and safeguard resources','Internal controls help an organization address risks related to operations, reporting, and compliance.',10,2,array['controls'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1791','accounting','Statements','medium','classic','What is materiality in financial reporting?','["Whether information could influence users'' decisions","Whether a document is printed on heavy paper","Whether every account has a round balance","Whether a report contains photographs"]'::jsonb,'Whether information could influence users'' decisions','Information is material if omitting, misstating, or obscuring it could reasonably influence users'' decisions.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1792','accounting','Audit','medium','classic','What is audit evidence?','["Information used by an auditor to reach conclusions","A guarantee that a company will never fail","A list of all future sales","A receipt that must always be handwritten"]'::jsonb,'Information used by an auditor to reach conclusions','Audit evidence includes information used to support the auditor''s findings and opinion.',10,2,array['audit'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1793','accounting','Accruals','medium','classic','What is an allowance for doubtful accounts intended to estimate?','["Receivables that may not be collected","The number of new customers next year","The amount of cash in a petty-cash box","The cost of replacing every computer"]'::jsonb,'Receivables that may not be collected','An allowance estimates expected credit losses or uncollectible amounts on receivables under the applicable framework.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1794','accounting','Reporting','medium','classic','What is an accounting period?','["A span of time covered by financial reports","The time between two bank branches","A rule that all invoices expire in one day","The number of entries in a single journal"]'::jsonb,'A span of time covered by financial reports','An accounting period is the interval for which financial results and position are reported.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1795','accounting','Statements','medium','classic','What is an operating expense?','["A cost incurred in the ordinary activities of a business","The purchase price of a long-term building only","An owner''s personal household payment","A loan principal balance"]'::jsonb,'A cost incurred in the ordinary activities of a business','Operating expenses are costs of running the ordinary activities of a business, rather than direct capital purchases.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1796','accounting','Bookkeeping','medium','classic','Why are source documents such as invoices and receipts retained?','["They provide evidence supporting recorded transactions","They automatically calculate the company''s tax bill","They replace the general ledger","They guarantee that every customer will pay"]'::jsonb,'They provide evidence supporting recorded transactions','Source documents provide an audit trail and evidence for transactions entered into accounting records.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1797','commerce','Documents','medium','classic','Which document formally requests specified goods or services from a supplier?','["A buyer''s formal request to purchase specified goods or services","A seller''s proof that money has been received","A document that replaces all delivery records","A bank statement from a supplier"]'::jsonb,'A buyer''s formal request to purchase specified goods or services','A purchase order specifies what a buyer is requesting and the agreed purchasing details.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1798','commerce','Documents','medium','classic','What does a packing list usually describe?','["The contents and quantities in a shipment","The buyer''s annual tax return","The driver''s medical history","The seller''s advertising plan"]'::jsonb,'The contents and quantities in a shipment','A packing list itemizes the contents of a shipment to help with handling and checking delivery.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1799','commerce','Documents','medium','classic','What does a certificate of origin identify?','["The country where goods are considered to originate","The name of the final delivery driver","The temperature of a warehouse","The retail price in every destination market"]'::jsonb,'The country where goods are considered to originate','A certificate of origin states the country of origin of goods for trade or customs purposes.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1800','commerce','Payments','medium','classic','What is a letter of credit used for in international trade?','["A bank''s conditional undertaking to pay when stated documents are presented","A letter that guarantees every shipment arrives on time","A receipt proving a buyer has paid cash","A customs tax charged on all services"]'::jsonb,'A bank''s conditional undertaking to pay when stated documents are presented','A letter of credit is a bank commitment to pay a beneficiary if the required terms and documents are met.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1801','commerce','Logistics','medium','classic','What does a freight forwarder commonly arrange?','["Transportation and related logistics for a shipment","The design of a product''s logo","The buyer''s annual company audit","The sale of a business''s shares"]'::jsonb,'Transportation and related logistics for a shipment','A freight forwarder coordinates shipment arrangements and related logistics on behalf of a shipper.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1802','commerce','Logistics','medium','classic','What is last-mile delivery?','["The final leg of a delivery to its destination","The first step in manufacturing a product","A method for measuring warehouse temperature","The distance between two countries'' capitals"]'::jsonb,'The final leg of a delivery to its destination','Last-mile delivery is the final part of moving goods from a distribution point to the recipient.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1803','commerce','Logistics','medium','classic','What is reverse logistics?','["Moving goods back through a supply chain for return, repair, or recovery","Transporting goods only from a factory to a shop","A plan for reversing a truck in a driveway","A way to make every shipment travel twice as fast"]'::jsonb,'Moving goods back through a supply chain for return, repair, or recovery','Reverse logistics handles returns and the recovery, repair, recycling, or disposal of products and materials.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1804','commerce','Trade','medium','classic','What is a trade balance?','["The value of exports compared with the value of imports","The number of traders in a market","The cost of a country''s national flag","A list of all goods in a shop"]'::jsonb,'The value of exports compared with the value of imports','A trade balance compares a country''s exports and imports over a period.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1805','commerce','Payments','easy','classic','When is payment collected in a cash-on-delivery transaction?','["Payment is collected when goods are delivered","Payment is made only after one year","Goods are delivered without any payment ever","The customer pays before placing an order"]'::jsonb,'Payment is collected when goods are delivered','Cash on delivery requires payment at the time goods are delivered, according to the seller''s terms.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1806','commerce','Warehousing','medium','classic','What is cycle counting in inventory management?','["Counting selected stock items on a rotating schedule","Counting every customer once a year","Measuring the circumference of a delivery route","Checking the age of a cash register"]'::jsonb,'Counting selected stock items on a rotating schedule','Cycle counting verifies portions of inventory on an ongoing schedule rather than counting everything at once.',10,2,array['warehousing'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1807','commerce','Trade','medium','classic','What is a customs declaration?','["Information submitted about goods crossing a border","A promise that an item can never be returned","A list of local shop opening hours","A shipping label with no description of contents"]'::jsonb,'Information submitted about goods crossing a border','A customs declaration provides details about goods being imported or exported for customs processing.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1808','commerce','Supply chains','medium','classic','What network links the organizations and activities that provide a product?','["The linked organizations and activities involved in providing a product","A chain used to secure a warehouse gate","A list of one company''s office supplies","A route used only for transporting letters"]'::jsonb,'The linked organizations and activities involved in providing a product','A supply chain connects organizations and processes involved in sourcing, making, moving, and delivering products.',10,2,array['supply chains'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1809','commerce','Documents','medium','classic','What is a bill of exchange?','["A written order directing one party to pay a stated amount","A receipt for goods already returned","A document showing a product''s color","A list of bank holidays"]'::jsonb,'A written order directing one party to pay a stated amount','A bill of exchange is a written instrument ordering a drawee to pay a specified sum under stated terms.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1810','commerce','Trade','medium','classic','What is a customs duty?','["A tax imposed on goods crossing a customs border","A fee paid to store a product at home","A discount given to a wholesale customer","A payment made to a delivery driver as a tip"]'::jsonb,'A tax imposed on goods crossing a customs border','A customs duty is a tax or charge imposed on certain imported or exported goods.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1811','commerce','Payments','medium','classic','What are payment terms in a commercial sale?','["The agreed timing and conditions for paying an invoice","The list of goods held by a carrier","The quality standards for a factory","A company''s annual staff schedule"]'::jsonb,'The agreed timing and conditions for paying an invoice','Payment terms state when and how a buyer is expected to pay an invoice.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1812','commerce','Retail','medium','classic','What is a point-of-sale system used to do?','["Process purchases and record sales at checkout","Make a product without any materials","Transport a shipment across an ocean","Decide the result of a court hearing"]'::jsonb,'Process purchases and record sales at checkout','A point-of-sale system supports checkout, payment processing, and recording sales transactions.',10,2,array['retail'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1813','commerce','Supply chains','medium','classic','What does traceability mean in a supply chain?','["The ability to follow a product''s history or movement","A guarantee that no product will ever be recalled","The speed at which a barcode is printed","The total amount of tax paid by every company"]'::jsonb,'The ability to follow a product''s history or movement','Traceability lets organizations track products, components, or materials through stages of a supply chain.',10,2,array['supply chains'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1814','commerce','Retail','easy','classic','What is a barcode commonly used for in commerce?','["Identifying an item so its data can be scanned","Encrypting a telephone conversation","Measuring the weight of a truck from space","Printing a legal contract automatically"]'::jsonb,'Identifying an item so its data can be scanned','Barcodes encode identifying data that can be read by a scanner at checkout or during inventory work.',10,2,array['retail'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1815','commerce','Trade','medium','classic','What is countertrade?','["A trade arrangement in which goods or services are exchanged partly or wholly for other goods or services","A sale made only at a retail counter","A method for counting imported products twice","A bank loan repaid only with coins"]'::jsonb,'A trade arrangement in which goods or services are exchanged partly or wholly for other goods or services','Countertrade links a purchase to an exchange of goods or services rather than relying solely on cash payment.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1816','commerce','Logistics','medium','classic','What is a cold chain?','["A temperature-controlled supply chain for sensitive goods","A chain made only of frozen metal","A route used only during winter","A system for cooling shop lights"]'::jsonb,'A temperature-controlled supply chain for sensitive goods','A cold chain maintains required temperature conditions as products such as food or medicines are stored and transported.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1817','mathematics','Number sense','easy','classic','What is a prime number?','["A whole number greater than 1 with exactly two positive factors","A whole number that is divisible by every number","Any number with a decimal part","A number that has no factors"]'::jsonb,'A whole number greater than 1 with exactly two positive factors','A prime number has exactly two positive divisors: 1 and itself.',10,2,array['number sense'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1818','mathematics','Number sense','easy','classic','What is the least common multiple of two or more numbers?','["The smallest positive number that is a multiple of all of them","The largest number that divides only one of them","The sum of all their digits","The first number in a multiplication table"]'::jsonb,'The smallest positive number that is a multiple of all of them','The least common multiple is the smallest positive integer divisible by each number in the set.',10,2,array['number sense'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1819','mathematics','Number sense','easy','classic','What is the greatest common factor of two whole numbers?','["The largest positive integer that divides both numbers","The smallest positive number in either set","The sum of their squares","A number that is larger than both"]'::jsonb,'The largest positive integer that divides both numbers','The greatest common factor is the largest positive integer that divides each of the given integers.',10,2,array['number sense'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1820','mathematics','Geometry','easy','classic','What is the sum of the interior angles of a triangle in Euclidean geometry?','["180 degrees","90 degrees","270 degrees","360 degrees"]'::jsonb,'180 degrees','The three interior angles of a triangle in flat Euclidean geometry sum to 180 degrees.',10,2,array['geometry'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1821','mathematics','Geometry','easy','classic','What is the area of a square with side length s?','["s squared","4s","2s","s divided by 4"]'::jsonb,'s squared','A square''s area is its side length multiplied by itself, written s squared.',10,2,array['geometry'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1822','mathematics','Geometry','medium','classic','What is the circumference of a circle with radius r?','["2 pi r","pi r squared","r divided by 2 pi","4 pi r squared"]'::jsonb,'2 pi r','A circle''s circumference is 2 pi times its radius, or pi times its diameter.',10,2,array['geometry'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1823','mathematics','Number sense','easy','classic','What does percent mean?','["Per one hundred","Per one thousand","Per ten","Per one million"]'::jsonb,'Per one hundred','Percent means per hundred; for example, 25 percent is 25 out of 100.',10,2,array['number sense'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1824','mathematics','Fractions','easy','classic','In the fraction 5 over 8, what is the denominator?','["8","5","13","40"]'::jsonb,'8','The denominator is the bottom number of a fraction; it names the number of equal parts in the whole.',10,2,array['fractions'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1825','mathematics','Fractions','easy','classic','What is the absolute value of negative 7?','["7","Negative 7","0","14"]'::jsonb,'7','Absolute value is distance from zero on the number line, so the absolute value of negative 7 is 7.',10,2,array['fractions'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1826','mathematics','Statistics','medium','classic','How is the median of a data set found?','["Sort the values and find the middle value","Add the largest and smallest values only","Choose the value that occurs most often","Multiply every value by the number of values"]'::jsonb,'Sort the values and find the middle value','The median is the middle value after the data are arranged in order; for an even count, it is the mean of the two middle values.',10,2,array['statistics'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1827','mathematics','Statistics','easy','classic','What is the mode of a data set?','["The value or values that occur most often","The difference between the largest and smallest values","The sum of all values divided by two","The middle value after sorting"]'::jsonb,'The value or values that occur most often','The mode is the value or values with the greatest frequency in a data set.',10,2,array['statistics'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1828','mathematics','Statistics','easy','classic','How is the arithmetic mean calculated?','["Add the values and divide by how many values there are","Subtract the smallest value from the largest","Select the value in the middle","Multiply the values together"]'::jsonb,'Add the values and divide by how many values there are','The arithmetic mean is the sum of the observations divided by the number of observations.',10,2,array['statistics'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1829','mathematics','Geometry','easy','classic','What does the perimeter of a shape measure?','["The total distance around its boundary","The amount of space inside it","Its mass","The height of its tallest point only"]'::jsonb,'The total distance around its boundary','Perimeter is the total length of the boundary around a two-dimensional shape.',10,2,array['geometry'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1830','mathematics','Geometry','easy','classic','How many degrees are in a right angle?','["90","45","180","360"]'::jsonb,'90','A right angle measures 90 degrees.',10,2,array['geometry'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1831','mathematics','Ratios','easy','classic','What does a ratio compare?','["Two or more quantities by division","Only the temperature of two objects","The sum of every number in a set","The distance around a circle"]'::jsonb,'Two or more quantities by division','A ratio expresses a multiplicative comparison between quantities, commonly by division.',10,2,array['ratios'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1832','mathematics','Measurement','easy','classic','How many metres are in one kilometre?','["1,000","100","10","10,000"]'::jsonb,'1,000','The metric prefix kilo means one thousand, so one kilometre equals 1,000 metres.',10,2,array['measurement'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1833','mathematics','Fractions','easy','classic','What decimal is equal to the fraction three quarters?','["0.75","0.34","0.25","1.25"]'::jsonb,'0.75','Three divided by four equals 0.75.',10,2,array['fractions'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1834','mathematics','Number sense','medium','classic','What is the product of two negative integers?','["A positive integer","A negative integer","Always zero","An irrational number"]'::jsonb,'A positive integer','Multiplying two negative numbers gives a positive product.',10,2,array['number sense'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1835','mathematics','Geometry','medium','classic','Which formula relates the sides of a right triangle?','["a squared plus b squared equals c squared","a plus b equals c squared","a times b equals c","a squared minus b squared equals c"]'::jsonb,'a squared plus b squared equals c squared','The Pythagorean theorem states that the squares of the two shorter sides sum to the square of the hypotenuse.',10,2,array['geometry'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1836','mathematics','Algebra','easy','classic','What is 2 raised to the power of 3?','["8","6","9","12"]'::jsonb,'8','Two cubed means 2 multiplied by itself three times: 2 times 2 times 2 equals 8.',10,2,array['algebra'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
