insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1838','health','Body systems','easy','classic','Which bones protect the brain?','["The skull","The ribs","The pelvis","The kneecaps"]'::jsonb,'The skull','The bones of the skull enclose and protect the brain.',10,2,array['body systems'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1839','health','Body systems','medium','classic','What does the diaphragm help the body do?','["Breathe by changing pressure in the chest","Digest food in the stomach","Pump blood through the heart","Filter waste in the kidneys"]'::jsonb,'Breathe by changing pressure in the chest','The diaphragm is a major breathing muscle that changes the volume and pressure of the chest cavity.',10,2,array['body systems'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1840','health','Medicines','medium','classic','Antibiotics are designed to treat infections caused by what?','["Bacteria","Viruses such as the common cold","Broken bones","Seasonal pollen"]'::jsonb,'Bacteria','Antibiotics act against bacteria; they do not treat viral infections such as colds or flu.',10,2,array['medicines'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1841','health','Oral health','easy','classic','What is tooth enamel?','["The hard outer covering of a tooth","The soft center of a tooth","A muscle beneath the tongue","A gland that produces saliva"]'::jsonb,'The hard outer covering of a tooth','Enamel is the hard outer layer that covers and protects the visible part of a tooth.',10,2,array['oral health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
