insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1844','health','Hygiene','easy','classic','Why is washing hands with soap and water useful?','["It helps remove germs and dirt from hands","It makes the immune system unnecessary","It sterilizes every object in a room","It prevents every possible infection"]'::jsonb,'It helps remove germs and dirt from hands','Handwashing with soap and water helps remove dirt and germs and can reduce the spread of infection.',10,2,array['hygiene'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
