insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1846','health','Body systems','easy','classic','What do the kidneys do as part of the urinary system?','["Filter blood and help form urine","Pump air into the lungs","Produce sound for speech","Move food through the esophagus"]'::jsonb,'Filter blood and help form urine','The kidneys filter blood, regulate fluid and electrolyte balance, and produce urine.',10,2,array['body systems'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1847','health','Body systems','easy','classic','Where does most gas exchange between air and blood take place?','["In tiny air sacs in the lungs","Inside the stomach","Across the surface of the skin only","In the bones of the legs"]'::jsonb,'In tiny air sacs in the lungs','Gas exchange occurs mainly across the thin walls of alveoli, tiny air sacs in the lungs.',10,2,array['body systems'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1848','health','Body systems','medium','classic','What is a pulse?','["The rhythmic expansion of an artery as the heart beats","The amount of air in a room","A muscle that moves the eye","A type of bone in the wrist"]'::jsonb,'The rhythmic expansion of an artery as the heart beats','A pulse is the rhythmic pressure wave in an artery produced by each heartbeat.',10,2,array['body systems'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1849','health','Body systems','easy','classic','What is one major role of platelets in blood?','["Help form clots to limit bleeding","Carry most oxygen to tissues","Produce stomach acid","Control the body''s balance"]'::jsonb,'Help form clots to limit bleeding','Platelets help blood clot at an injury and limit bleeding.',10,2,array['body systems'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
