insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1896','food','Cooking methods','medium','classic','What is a water bath used for in some cooking and baking?','["Gentle, even heat around a dish","Freezing a dish without a freezer","Adding a crust by direct flame","Measuring the acidity of a liquid"]'::jsonb,'Gentle, even heat around a dish','A water bath surrounds a cooking vessel with hot water to moderate heat and reduce sudden temperature changes.',10,2,array['cooking methods'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict (id) do nothing;
