insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1902','arts','Art materials','easy','classic','In visual art, what does medium mean?','["The material or materials used to make an artwork","The age of the person viewing the work","The price of the gallery ticket","The distance between two museums"]'::jsonb,'The material or materials used to make an artwork','An artwork''s medium is the material or combination of materials used to create it.',10,2,array['art materials'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
